if __name__ == "__main__":
    (DATA / "resumenes.json").write_text(json.dumps({k: {"r": v[0], "f": v[1]} for k, v in R.items()}, ensure_ascii=False, indent=1), encoding="utf-8")
    print(len(R), "resúmenes ->", DATA / "resumenes.json")
